// KQL syntax highlighting for the stafftools audit log query box.
// Replaces the textarea with a CodeMirror 6 editor, keeping the textarea
// synced for form submission and exposing helpers for the date-filter.

import {observe} from '@github/selector-observer'
import {EditorView, keymap, placeholder} from '@codemirror/view'
import {EditorState} from '@codemirror/state'
import {sql, SQLDialect} from '@codemirror/lang-sql'
import {autocompletion, closeBrackets, closeBracketsKeymap, completeFromList, ifIn} from '@codemirror/autocomplete'
import {HighlightStyle, syntaxHighlighting} from '@codemirror/language'
import {tags} from '@lezer/highlight'

const kqlDialect = SQLDialect.define({
  keywords:
    'where summarize project extend join lookup let datatable union render ' +
    'sort top limit count distinct as by on asc desc if print alias materialize ' +
    'order take search find has contains startswith endswith and or not between in',
  builtin:
    'ago now bin startofday startofweek startofmonth datetime timespan ' +
    'long int string bool real dynamic todatetime tostring toint tolong',
  operatorChars: '+-*/<>=!|&',
  doubleQuotedStrings: true,
})

// Uses Primer's prettylights variables so colors adapt to light/dark mode automatically.
const highlightStyle = HighlightStyle.define([
  {tag: tags.keyword, color: 'var(--color-prettylights-syntax-keyword, #cf222e)'},
  {tag: tags.standard(tags.name), color: 'var(--color-prettylights-syntax-entity, #6639ba)'},
  {tag: tags.string, color: 'var(--color-prettylights-syntax-string, #0a3069)'},
  {tag: tags.number, color: 'var(--color-prettylights-syntax-constant, #0550ae)'},
  {tag: tags.bool, color: 'var(--color-prettylights-syntax-constant, #0550ae)'},
  {tag: tags.operator, color: 'var(--color-prettylights-syntax-keyword, #cf222e)'},
  {tag: tags.comment, color: 'var(--color-prettylights-syntax-comment, #6e7781)', fontStyle: 'italic'},
])

let view: EditorView | null = null

export const getAuditLogEditorValue = (): string | null => view?.state.doc.toString() ?? null

export function setAuditLogEditorValue(value: string): void {
  if (view) view.dispatch({changes: {from: 0, to: view.state.doc.length, insert: value}})
}

const theme = EditorView.theme({
  '&': {
    border: '1px solid var(--borderColor-default, #d0d7de)',
    borderRadius: 'var(--borderRadius-medium, 6px)',
    fontSize: '14px',
    backgroundColor: 'var(--bgColor-default, #fff)',
    color: 'var(--fgColor-default, #1f2328)',
  },
  '.cm-content': {
    fontFamily:
      'var(--fontStack-monospace, ui-monospace, SFMono-Regular, SF Mono, Menlo, Consolas, Liberation Mono, monospace)',
    padding: '8px 4px',
    minHeight: '200px',
    caretColor: 'var(--fgColor-default, #1f2328)',
  },
  '.cm-placeholder': {height: 0},
  '.cm-line': {lineHeight: '1.5'},
  '&.cm-focused': {outline: '2px solid var(--focus-outlineColor, #0969da)', outlineOffset: '-1px'},
  '.cm-scroller': {overflow: 'auto'},
  '.cm-tooltip-autocomplete': {
    border: '1px solid var(--borderColor-default, #d0d7de)',
    borderRadius: 'var(--borderRadius-medium, 6px)',
    backgroundColor: 'var(--overlay-bgColor, var(--bgColor-default, #fff))',
    boxShadow: 'var(--shadow-floating-small, 0 1px 3px rgba(31,35,40,0.12), 0 8px 24px rgba(66,74,83,0.12))',
    fontFamily:
      'var(--fontStack-monospace, ui-monospace, SFMono-Regular, SF Mono, Menlo, Consolas, Liberation Mono, monospace)',
    fontSize: '14px',
    color: 'var(--fgColor-default, #1f2328)',
    minWidth: '280px',
    padding: '4px 0',
  },
  '.cm-tooltip-autocomplete ul': {maxHeight: '20em'},
  '.cm-tooltip-autocomplete ul li': {
    padding: '7px 12px',
    lineHeight: '1.5',
    borderRadius: '3px',
    margin: '0 4px',
  },
  '.cm-tooltip-autocomplete ul li[aria-selected]': {
    backgroundColor: 'var(--bgColor-accent-emphasis, #0969da)',
    color: 'var(--fgColor-onEmphasis, #fff)',
  },
  '.cm-completionIcon': {display: 'none'},
  '.cm-completionMatchedText': {textDecoration: 'none', fontWeight: 'bold'},
})

observe('.js-audit-log-kql-editor', {
  add(textarea) {
    if (!(textarea instanceof HTMLTextAreaElement)) return
    if (textarea.getAttribute('data-codemirror-initialized')) return
    textarea.setAttribute('data-codemirror-initialized', 'true')

    const form = textarea.closest('form')
    const actions: string[] = JSON.parse(textarea.getAttribute('data-audit-actions') || '[]')
    textarea.style.display = 'none'

    const container = document.createElement('div')
    container.className = 'tmp-mb-3'
    textarea.insertAdjacentElement('afterend', container)

    // Inherit ARIA attributes from the textarea so the editor is accessible.
    const ariaLabel =
      textarea.getAttribute('aria-label') ||
      textarea.getAttribute('aria-labelledby') ||
      document.querySelector<HTMLLabelElement>(`label[for="${textarea.id}"]`)?.textContent?.trim() ||
      'Query'

    view = new EditorView({
      parent: container,
      state: EditorState.create({
        doc: textarea.value,
        extensions: [
          EditorView.contentAttributes.of({role: 'textbox', 'aria-label': ariaLabel, 'aria-multiline': 'true'}),
          sql({dialect: kqlDialect}),
          closeBrackets(),
          placeholder(textarea.placeholder || ''),
          autocompletion({override: [ifIn(['String'], completeFromList(actions))]}),
          syntaxHighlighting(highlightStyle),
          EditorView.lineWrapping,
          EditorView.updateListener.of(u => {
            if (u.docChanged) textarea.value = u.state.doc.toString()
          }),
          keymap.of([
            ...closeBracketsKeymap,
            {
              key: 'Mod-Enter',
              run: () => {
                form?.submit()
                return true
              },
            },
          ]),
          theme,
        ],
      }),
    })
    view.focus()
  },
})
