import {observe} from '@github/selector-observer'
import {on} from 'delegated-events'
import {getAuditLogEditorValue, setAuditLogEditorValue} from './audit-log-kql-editor'

const STORAGE_KEY = 'audit-log-date-filter-open'

observe('.js-audit-log-date-filter', {
  initialize(container) {
    const details = container.querySelector<HTMLDetailsElement>('.js-audit-log-date-details')
    const startDate = container.querySelector<HTMLInputElement>('.js-audit-log-start-date')
    const endDate = container.querySelector<HTMLInputElement>('.js-audit-log-end-date')
    const queryTextarea = container.querySelector<HTMLTextAreaElement>('.js-audit-log-query')

    if (!details || !startDate || !endDate || !queryTextarea) return

    // Restore details open/closed state from localStorage
    const savedState = localStorage.getItem(STORAGE_KEY)
    if (savedState === 'true') {
      details.open = true
    } else if (savedState === 'false') {
      details.open = false
    }

    // Save state when toggled (toggle doesn't bubble, so we attach directly)
    details.addEventListener('toggle', () => {
      localStorage.setItem(STORAGE_KEY, String(details.open))
    })

    // Populate date inputs from existing query
    const query = queryTextarea.value
    const startMatch = query.match(/\| where _timestamp >= datetime\('(\d{4}-\d{2}-\d{2})'\)/)
    if (startMatch?.[1]) {
      startDate.value = startMatch[1]
    }
    const endMatch = query.match(/\| where _timestamp <= datetime\('(\d{4}-\d{2}-\d{2})'\)/)
    if (endMatch?.[1]) {
      endDate.value = endMatch[1]
    }
  },
})

// Update query when dates change
on('change', '.js-audit-log-start-date, .js-audit-log-end-date', event => {
  const container = (event.currentTarget as Element).closest('.js-audit-log-date-filter')
  if (!container) return
  updateQuery(container)
})

// Clear dates button
on('click', '.js-audit-log-clear-dates', event => {
  event.preventDefault()
  const container = (event.currentTarget as Element).closest('.js-audit-log-date-filter')
  if (!container) return

  const startDate = container.querySelector<HTMLInputElement>('.js-audit-log-start-date')
  const endDate = container.querySelector<HTMLInputElement>('.js-audit-log-end-date')
  if (startDate) startDate.value = ''
  if (endDate) endDate.value = ''
  updateQuery(container)
})

function updateQuery(container: Element) {
  const startDate = container.querySelector<HTMLInputElement>('.js-audit-log-start-date')
  const endDate = container.querySelector<HTMLInputElement>('.js-audit-log-end-date')
  const queryTextarea = container.querySelector<HTMLTextAreaElement>('.js-audit-log-query')

  if (!startDate || !endDate || !queryTextarea) return

  // Read from CodeMirror if active (it may be ahead of the textarea)
  let query = getAuditLogEditorValue() ?? queryTextarea.value

  // Remove existing date filters
  query = query.replace(/\n?\| where _timestamp >= datetime\('[^']*'\)/g, '')
  query = query.replace(/\n?\| where _timestamp <= datetime\('[^']*'\)/g, '')
  query = query.trim()

  // Add new date filters
  if (startDate.value) {
    query += `\n| where _timestamp >= datetime('${startDate.value}')`
  }
  if (endDate.value) {
    query += `\n| where _timestamp <= datetime('${endDate.value}')`
  }

  queryTextarea.value = query

  // If CodeMirror is active, update it to reflect the new textarea value
  setAuditLogEditorValue(query)
}
